PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('owner','member')), created_at INTEGER NOT NULL, settings_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE credentials (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, public_key TEXT NOT NULL, counter INTEGER NOT NULL, transports_json TEXT NOT NULL, device_type TEXT NOT NULL, backed_up INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX credentials_user ON credentials(user_id);
CREATE TABLE invitations (token_hash TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('owner','member')), expires_at INTEGER NOT NULL);
CREATE TABLE auth_flows (id_hash TEXT PRIMARY KEY, state TEXT NOT NULL, pkce_challenge TEXT NOT NULL, challenge TEXT, mode TEXT, pending_user_id TEXT, expires_at INTEGER NOT NULL);
CREATE TABLE auth_codes (code_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, pkce_challenge TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE imports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, ranges_json TEXT NOT NULL, translation TEXT, source_url TEXT, created_at INTEGER NOT NULL, UNIQUE(user_id,idempotency_key));
CREATE INDEX imports_user_date ON imports(user_id,created_at DESC);
CREATE TABLE conversations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, import_id TEXT NOT NULL REFERENCES imports(id) ON DELETE CASCADE, passage_json TEXT NOT NULL, spoiler_allowed INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(id,user_id));
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content_json TEXT NOT NULL, created_at INTEGER NOT NULL, FOREIGN KEY(conversation_id,user_id) REFERENCES conversations(id,user_id) ON DELETE CASCADE);
CREATE INDEX messages_conversation ON messages(user_id,conversation_id,created_at);
CREATE TABLE generation_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, conversation_id TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('reserved','running','complete','failed','cancelled')), result_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(id,user_id));
CREATE TABLE budget_days (day TEXT PRIMARY KEY, reserved INTEGER NOT NULL DEFAULT 0, consumed INTEGER NOT NULL DEFAULT 0, CHECK(reserved>=0),CHECK(consumed>=0));
CREATE TABLE user_budget_days (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, consumed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day),CHECK(reserved>=0),CHECK(consumed>=0));
CREATE TABLE budget_reservations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), actual INTEGER, state TEXT NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','settled')), created_at INTEGER NOT NULL);
CREATE TABLE rate_windows (scope TEXT NOT NULL, window INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(scope,window));
CREATE TABLE public_sources (id TEXT PRIMARY KEY, book TEXT NOT NULL, start_chapter INTEGER NOT NULL, start_verse INTEGER NOT NULL, end_chapter INTEGER NOT NULL, end_verse INTEGER NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, content_json TEXT NOT NULL, version TEXT NOT NULL, rights_status TEXT NOT NULL CHECK(rights_status IN ('approved','revoked','pending')), active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX sources_passage ON public_sources(book,start_chapter,end_chapter,active);
CREATE TABLE public_cache (cache_key TEXT PRIMARY KEY, source_version TEXT NOT NULL, body_json TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE model_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, model_id TEXT NOT NULL, settings_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE comparison_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, request_hash TEXT NOT NULL, status TEXT NOT NULL, saved INTEGER NOT NULL DEFAULT 0, metrics_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_active_comparison ON comparison_jobs(user_id) WHERE status IN ('reserved','running');
